import { test } from "node:test";
import assert from "node:assert/strict";
import { slugify } from "../src/slug.ts";

test("collapses runs of separators", () => {
  assert.equal(slugify("Hello  World!"), "hello-world");
});

test("trims hyphens from both edges", () => {
  assert.equal(slugify("--Hello  World!--"), "hello-world");
  assert.equal(slugify("!!!"), "");
});

test("folds accented letters to ASCII", () => {
  assert.equal(slugify("Café au lait"), "cafe-au-lait");
  assert.equal(slugify("Añejo Ünder Fjörd"), "anejo-under-fjord");
});

test("keeps digits and single hyphens intact", () => {
  assert.equal(slugify("Top 10 - Tips"), "top-10-tips");
});

